PANEL='''<section id="media"><h2>2. 4캠 동시 검수</h2><p>전처리와 동일하게 공통 구간에서 프레임 수가 가장 많은 카메라를 기준으로 선택하고, host_time_s 최근접 프레임을 25ms 허용치 안에서 표시합니다. 앞뒤 노출 trim 전 시간축입니다. RGB와 Depth는 같은 frame_idx를 사용합니다. 하드웨어 동기화 보장이 아니며 각 화면에 실제 시간 차이를 표시합니다.</p><p class="notice">Depth: 0–2m 회색조 / 무효값 빨강. 공통 구간 밖의 시작·끝은 아래 원본 영상에서 별도로 확인하세요. 이미지 로딩이 느리면 재생도 대기하며 8개 이미지를 함께 갱신합니다.</p>
<div class="sync-controls"><button id="prevFrame" disabled>이전 프레임</button><button id="playSync" disabled>같이 재생</button><button id="nextFrame" disabled>다음 프레임</button><label>속도 <select id="speed"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1" selected>1×</option></select></label><label>표시 <select id="viewMode"><option value="both">RGB + Depth</option><option value="rgb">RGB</option><option value="depth">Depth</option></select></label></div>
<input id="syncSlider" type="range" min="0" max="0" value="0" disabled aria-label="공통 촬영 시간"><p id="syncTime" role="status">타임스탬프와 프레임 준비 중…</p>
<div id="syncGrid" class="sync-grid">'''+''.join(f'''<article class="sync-camera"><h3>Camera {c} <button type="button" class="expand-cam" data-cam="{c}">확대</button></h3><p id="frameMeta{c}" class="muted"></p><div class="paired"><figure class="rgb-view"><img id="syncRgb{c}" alt="Camera {c} RGB"><figcaption>RGB</figcaption></figure><figure class="depth-view"><img id="syncDepth{c}" alt="Camera {c} Depth"><figcaption>Depth</figcaption></figure></div></article>''' for c in range(1,5))+'''</div>
<div class="issue-box"><h3>보고 있는 시점에 문제 기록</h3><label>카메라 <select id="issueCam"><option value="all">전체 카메라</option><option>1</option><option>2</option><option>3</option><option>4</option></select></label> <label>문제 <select id="issueType"><option>잘림</option><option>가림</option><option>깊이 누락</option><option>시간 불일치</option><option>기타</option></select></label><input id="issueText" type="text" placeholder="위치·지속 구간·다른 시점 확인 결과를 적으세요"><button id="addIssue" disabled>현재 시점을 메모에 추가</button><p id="issueStatus" role="status">추가한 기록은 검수 메모에 들어갑니다. 승인 또는 보류 저장을 눌러야 파일에 저장됩니다.</p></div></section>'''
CSS='''.sync-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.sync-camera{background:#f3f6fa;border-radius:12px;padding:12px;min-width:0}.paired{display:grid;grid-template-columns:1fr 1fr;gap:8px}.sync-controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center}#syncSlider{width:100%;margin-top:18px}.sync-camera figure{margin:0}.sync-camera h3{display:flex;justify-content:space-between;align-items:center}.sync-camera button{padding:4px 10px;font-size:13px}#syncGrid[data-mode=rgb] .depth-view,#syncGrid[data-mode=depth] .rgb-view{display:none}#syncGrid[data-mode=rgb] .paired,#syncGrid[data-mode=depth] .paired{grid-template-columns:1fr}.sync-camera.expanded{grid-column:1/-1}.issue-box{border-top:1px solid #ccd7e4;margin-top:18px;padding-top:12px}select{font:inherit;padding:6px}.sync-camera .muted{font-size:12px;overflow-wrap:anywhere}@media(max-width:700px){.sync-grid{gap:6px}.sync-camera{padding:6px}}'''
JS='''
let syncData=null,syncIndex=-1,playing=false,playTimer=null,requestId=0;
function pauseSync(){playing=false;clearTimeout(playTimer);$('playSync').textContent='같이 재생';}
function imageLoad(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('이미지 로딩 실패: '+src));im.src=src;});}
async function displayFrame(index){
 const id=++requestId,row=syncData.frames[index];$('addIssue').disabled=true;
 try{const images=await Promise.all(row.cameras.flatMap(c=>['rgb','depth'].map(kind=>imageLoad('sync_media/cam_'+c.camera+'_'+String(c.frame).padStart(6,'0')+'_'+kind+'.jpg'))));
 if(id!==requestId)return false;
 row.cameras.forEach((c,j)=>{$('syncRgb'+c.camera).src=images[j*2].src;$('syncDepth'+c.camera).src=images[j*2+1].src;$('frameMeta'+c.camera).textContent=`frame ${c.frame} · host ${c.time.toFixed(6)} · 기준 대비 ${c.offset_ms>=0?'+':''}${c.offset_ms.toFixed(1)} ms`;});
 syncIndex=index;$('syncSlider').value=index;$('syncTime').textContent=`공통 구간 +${row.relative_s.toFixed(3)} / ${syncData.duration.toFixed(3)} s · ${index+1}/${syncData.frames.length} · host ${row.time.toFixed(6)}`;$('addIssue').disabled=false;return true;
 }catch(e){if(id===requestId){pauseSync();$('syncTime').textContent=e.message+' — 표시된 시점은 갱신되지 않았습니다.';}return false;}}
async function advance(){if(!playing)return;if(syncIndex>=syncData.frames.length-1){pauseSync();return;}const old=syncIndex;const start=performance.now();if(!await displayFrame(old+1))return;if(playing){const ms=(syncData.frames[syncIndex].time-syncData.frames[old].time)*1000/Number($('speed').value);playTimer=setTimeout(advance,Math.max(0,ms-(performance.now()-start)));}}
$('playSync').onclick=async()=>{if(playing){pauseSync();return;}if(syncIndex===syncData.frames.length-1)await displayFrame(0);playing=true;$('playSync').textContent='일시 정지';playTimer=setTimeout(advance,0);};
$('syncSlider').oninput=()=>{pauseSync();displayFrame(Number($('syncSlider').value));};
$('prevFrame').onclick=()=>{pauseSync();displayFrame(Math.max(0,syncIndex-1));};$('nextFrame').onclick=()=>{pauseSync();displayFrame(Math.min(syncData.frames.length-1,syncIndex+1));};
$('viewMode').onchange=()=>{$('syncGrid').dataset.mode=$('viewMode').value;};
document.querySelectorAll('.expand-cam').forEach(b=>b.onclick=()=>{const card=b.closest('article');card.classList.toggle('expanded');b.textContent=card.classList.contains('expanded')?'축소':'확대';});
$('addIssue').onclick=()=>{pauseSync();const desc=$('issueText').value.trim();if(!desc){$('issueStatus').textContent='문제 내용을 입력하세요.';return;}const row=syncData.frames[syncIndex],cam=$('issueCam').value;const matches=row.cameras.filter(c=>cam==='all'||String(c.camera)===cam).map(c=>`Camera ${c.camera} frame ${c.frame} (${c.offset_ms>=0?'+':''}${c.offset_ms}ms)`).join(', ');const entry=`[공통 +${row.relative_s.toFixed(3)}s / host ${row.time.toFixed(6)} / ${matches}] ${$('issueType').value}: ${desc}`;if($('note').value.length+entry.length+1>5000){$('issueStatus').textContent='검수 메모가 5000자를 초과합니다. 내용을 정리한 뒤 추가하세요.';return;}$('note').value+=($('note').value?'\\n':'')+entry;$('note').dispatchEvent(new Event('input'));$('issueText').value='';$('issueStatus').textContent='검수 메모에 추가됨 · 아직 파일에 저장되지 않았습니다. 승인 또는 보류 저장을 누르세요.';};
(async()=>{try{const r=await fetch('/api/sync?report='+encodeURIComponent(report));const d=await r.json();if(!r.ok)throw Error(d.error);syncData=d;$('syncSlider').max=d.frames.length-1;if(!await displayFrame(0))return;['prevFrame','playSync','nextFrame','syncSlider'].forEach(id=>$(id).disabled=false);}catch(e){$('syncTime').textContent='동시 검수 준비 실패: '+e.message;}})();
'''
